27: @Component
28: @RequiredArgsConstructor
29: public class StompAuthChannelInterceptor implements ChannelInterceptor {
30: 
31:     private final static Pattern ORGANIZATION_NOTIFICATION_TOPIC_PATTERN =
32:             Pattern.compile("^/topic/organizations/(?<organizationId>\\d+)/notifications$");
33: 
34:     private final AuthClientWrapper authClientWrapper;
35:     private final MainClient mainClient;
36: 
37:     @Override
38:     public Message<?> preSend(Message<?> message, MessageChannel channel) {
39:         StompHeaderAccessor accessor = MessageHeaderAccessor.getAccessor(message, StompHeaderAccessor.class);
40: 
41:         return switch (accessor.getCommand()) {
42:             case CONNECT -> handleConnectMessage(message, accessor);
43:             case SUBSCRIBE -> handleSubscribeMessage(message, accessor);
44:             case SEND, MESSAGE -> throw new ForbiddenException("You not allowed to send a message");
45:             default -> message;
46:         };
47: 
48:     }
49: 
50:     private Message<?> handleConnectMessage(Message<?> message, StompHeaderAccessor accessor) {
51:         String authorizationHeader = accessor.getFirstNativeHeader(HttpHeaders.AUTHORIZATION);
52: 
53:         try {
54:             Optional<String> accessToken = JwtUtils.getJwtTokenFromAuthorizationHeader(authorizationHeader);
55:             AuthResponse response = authClientWrapper.authorize(accessToken.orElse(null));
56: 
57:             accessor.setUser(() -> response.getId().toString());
58:             accessor.setLeaveMutable(true);
59:         } catch (UnauthorizedException e) {
60:             return null;
61:         }
62: 
63:         return MessageBuilder.createMessage(message.getPayload(), accessor.getMessageHeaders());
64:     }
65: 
66:     private Message<?> handleSubscribeMessage(Message<?> message, StompHeaderAccessor accessor) {
67:         if (isNull(accessor.getUser())) {
68:             return null;
69:         }
70: 
71:         if (nonNull(accessor.getDestination())) {
72:             Matcher matcher = ORGANIZATION_NOTIFICATION_TOPIC_PATTERN.matcher(accessor.getDestination());
73: 
74:             if (matcher.matches()) {
75:                 String organizationId = matcher.group("organizationId");
76:                 return handleSubscribeToOrganizationNotifications(message, accessor, Long.valueOf(organizationId));
77:             }
78:         }
79: 
80:         return message;
81:     }
82: 
83:     private Message<?> handleSubscribeToOrganizationNotifications(Message<?> message, StompHeaderAccessor accessor, Long organizationId) {
84:         UserExistsInOrganizationResponse userExistsInOrganization =
85:                 mainClient.isUserExistsInOrganization(organizationId, Long.valueOf(accessor.getUser().getName()));
86: 
87:         if (userExistsInOrganization.getIsUserExistsInOrganization()) {
88:             return message;
89:         }
90: 
91:         return null;
92:     }
93: }

